#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-cross-tier-freshness.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-cross-tier-freshness.mjs
 *
 * Refuses a composite (or page) if any consumed lower-tier component has
 * been edited AFTER the locked_sha the higher tier pinned.
 *
 * For each composite spec.yaml:
 *   - read consumed_atomics
 *   - for each entry, check git log of the atomic folder for commits later
 *     than locked_sha that modified <atomic-folder>/<Name>.tsx OR
 *     <atomic-folder>/__specs__/standards-compliance.yaml
 *   - if found, refuse: the lock is stale; either update locked_sha to the
 *     new HEAD and re-run the composite's verifier chain, OR revert the
 *     atomic to the pinned SHA.
 *
 * Same for pages and their consumed_composites + consumed_atomics.
 *
 * Usage:
 *   node verify-cross-tier-freshness.mjs <src-root-relative-to-cwd>
 *
 * Exit: 0 green, 1 red.
 */

import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import { execSync } from "node:child_process";
import { createRequire } from "node:module";

const RED = "\x1b[31m";
const GREEN = "\x1b[32m";
const YELLOW = "\x1b[33m";
const DIM = "\x1b[2m";
const RESET = "\x1b[0m";

function loadYaml() {
  try {
    const require = createRequire(process.cwd() + "/");
    return require("yaml");
  } catch {
    return null;
  }
}

function fail(msg) {
  process.stderr.write(`${RED}❌ verify-cross-tier-freshness:${RESET} ${msg}\n`);
  process.exit(1);
}

function ok(msg) {
  process.stdout.write(`${GREEN}✅ verify-cross-tier-freshness${RESET} — ${msg}\n`);
}

function warn(msg) {
  process.stdout.write(`${YELLOW}⚠  verify-cross-tier-freshness:${RESET} ${msg}\n`);
}

function findSpecsByTier(srcRoot, tier) {
  const found = [];
  const queue = [srcRoot];
  while (queue.length > 0) {
    const dir = queue.shift();
    if (!fs.existsSync(dir)) continue;
    let entries;
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
      continue;
    }
    for (const e of entries) {
      if (!e.isDirectory()) continue;
      if (e.name === "node_modules" || e.name.startsWith(".")) continue;
      const full = path.join(dir, e.name);
      const specPath = path.join(full, "__specs__", "spec.yaml");
      if (fs.existsSync(specPath)) {
        try {
          const text = fs.readFileSync(specPath, "utf8");
          if (new RegExp(`^\\s*tier:\\s*${tier}\\s*$`, "m").test(text)) {
            found.push({ folder: full, specPath });
            continue;
          }
        } catch {
          continue;
        }
      }
      queue.push(full);
    }
  }
  return found;
}

function checkFreshness(consumerFolder, consumed, label, repoRoot) {
  const violations = [];
  for (const dep of consumed ?? []) {
    if (!dep.path || !dep.locked_sha) continue;
    const absDep = path.resolve(repoRoot, dep.path);
    if (!fs.existsSync(absDep)) continue;
    try {
      const cmd = `git log "${dep.locked_sha}..HEAD" --oneline -- "${dep.path}"`;
      const output = execSync(cmd, {
        cwd: repoRoot,
        stdio: ["ignore", "pipe", "ignore"],
        encoding: "utf8",
      }).trim();
      if (output.length > 0) {
        const commits = output.split("\n").length;
        violations.push({
          consumer: consumerFolder,
          rule: `${label} "${dep.path}" pinned to ${dep.locked_sha} but has ${commits} commit(s) since — re-pin locked_sha to current HEAD and re-validate`,
        });
      }
    } catch {
      warn(
        `git log failed for ${dep.path} pinned to ${dep.locked_sha}; skipping freshness check (SHA may not exist in history yet)`,
      );
    }
  }
  return violations;
}

function main() {
  const arg = process.argv[2] || "src";
  const srcRoot = path.resolve(process.cwd(), arg);
  if (!fs.existsSync(srcRoot)) {
    ok(`no ${arg} dir; nothing to verify.`);
    return;
  }

  const yaml = loadYaml();
  if (!yaml) {
    fail("cannot resolve `yaml` package. Install it: pnpm add -Dw yaml");
  }

  let repoRoot;
  try {
    repoRoot = execSync("git rev-parse --show-toplevel", {
      cwd: process.cwd(),
      encoding: "utf8",
    }).trim();
  } catch {
    warn(`not inside a git repo; freshness check skipped.`);
    ok(`skipped (not a git repo).`);
    return;
  }

  const composites = findSpecsByTier(srcRoot, "composite");
  const pages = findSpecsByTier(srcRoot, "page");
  if (composites.length === 0 && pages.length === 0) {
    ok(`no composite or page specs under ${arg}; nothing to verify.`);
    return;
  }

  const allViolations = [];

  for (const c of composites) {
    let spec;
    try {
      spec = yaml.parse(fs.readFileSync(c.specPath, "utf8"));
    } catch {
      continue;
    }
    allViolations.push(...checkFreshness(c.folder, spec.consumed_atomics, "consumed atomic", repoRoot));
  }

  for (const p of pages) {
    let spec;
    try {
      spec = yaml.parse(fs.readFileSync(p.specPath, "utf8"));
    } catch {
      continue;
    }
    allViolations.push(...checkFreshness(p.folder, spec.consumed_composites, "consumed composite", repoRoot));
    allViolations.push(...checkFreshness(p.folder, spec.consumed_atomics, "consumed atomic", repoRoot));
  }

  if (allViolations.length === 0) {
    ok(
      `${composites.length} composite(s), ${pages.length} page(s) checked; no stale lower-tier dependencies.`,
    );
    return;
  }

  process.stderr.write(
    `${RED}❌ verify-cross-tier-freshness:${RESET} ${allViolations.length} stale dependency reference(s)\n\n`,
  );
  for (const v of allViolations) {
    process.stderr.write(
      `  ${path.relative(process.cwd(), v.consumer)}:\n    rule: ${v.rule}\n\n`,
    );
  }
  process.stderr.write(
    `${DIM}Either: (a) update locked_sha to the dep's current HEAD and re-run the consumer's verifier chain to re-validate; OR (b) revert the dep to the pinned SHA.${RESET}\n`,
  );
  process.exit(1);
}

main();
